-- composition of rule kernels cte_inlining x filter_pullup (duckdb), template not_exists
SELECT count(*) FROM (SELECT a1.c2 AS c0, '{"k": -1, "a": [1, 2, 3]}'::jsonb AS c1, a1.c0 AS c2, '1999-12-31'::date AS c3 FROM t0 AS a1 WHERE NULLIF ((NOT COALESCE (FALSE, (EXISTS (SELECT a1.c0 AS c0)))), TRUE)) AS ka WHERE NOT EXISTS (SELECT 1 FROM (SELECT 'x%'::text AS c0 EXCEPT ALL SELECT a1.c1 AS c0 FROM tl AS a1 WHERE (EXISTS (SELECT a1.c1 AS c0 FROM v0 AS a2 WHERE NULL::boolean))) AS kb);
-- pgfuzz:check kernel:not_exists SELECT CASE WHEN (SELECT count(*) FROM (SELECT 'x%'::text AS c0 EXCEPT ALL SELECT a1.c1 AS c0 FROM tl AS a1 WHERE (EXISTS (SELECT a1.c1 AS c0 FROM v0 AS a2 WHERE NULL::boolean))) AS kb) = 0 THEN (SELECT count(*) FROM (SELECT a1.c2 AS c0, '{"k": -1, "a": [1, 2, 3]}'::jsonb AS c1, a1.c0 AS c2, '1999-12-31'::date AS c3 FROM t0 AS a1 WHERE NULLIF ((NOT COALESCE (FALSE, (EXISTS (SELECT a1.c0 AS c0)))), TRUE)) AS ka) ELSE 0 END
